<div class="space-y-6 p-6"><div><h1 class="text-2xl font-semibold">Reconciliação bancária</h1><p class="text-sm text-zinc-500">Liga movimentos bancários aos pagamentos e documentos da empresa.</p></div><form wire:submit="reconcile" class="grid gap-3 rounded-2xl border bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900 md:grid-cols-4"><select wire:model="transactionId" class="rounded-lg border p-2"><option value="">Movimento bancário</option>@foreach($transactions as $t)<option value="{{ $t->id }}">{{ $t->transaction_date->format('d/m/Y') }} — {{ number_format($t->amount,2,',',' ') }} — {{ $t->description }}</option>@endforeach</select><select wire:model="matchedType" class="rounded-lg border p-2"><option value="payment_allocation">Pagamento</option><option value="invoice">Fatura</option><option value="expense">Despesa</option></select><select wire:model="matchedId" class="rounded-lg border p-2">@if($matchedType==='payment_allocation') @foreach($payments as $p)<option value="{{ $p->id }}">Pagamento #{{ $p->id }} — {{ number_format($p->amount,2,',',' ') }}</option>@endforeach @elseif($matchedType==='invoice') @foreach($invoices as $i)<option value="{{ $i->id }}">{{ $i->invoice_number }} — {{ number_format($i->total_amount,2,',',' ') }}</option>@endforeach @else @foreach($expenses as $e)<option value="{{ $e->id }}">{{ $e->title ?: $e->description }} — {{ number_format($e->amount,2,',',' ') }}</option>@endforeach @endif</select><button class="rounded-lg bg-zinc-900 px-4 py-2 text-white">Reconciliar</button></form>@if($errors->any())<div class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ $errors->first() }}</div>@endif</div>
